const assert = require('node:assert/strict');
const { Ledger } = require('../.build/ledger');
const { PaymentService } = require('../.build/service');
const { Transient } = require('../.build/transport');

async function main() {
  const ledger = new Ledger();
  const acknowledged = [];
  const service = new PaymentService(ledger, {
    acknowledge: async receipt => { acknowledged.push(receipt); },
  });
  const receipts = await Promise.all(Array.from({ length: 10 }, () => service.pay('shop', 'sale', 123)));
  receipts.forEach(receipt => assert.equal(receipt, receipts[0]));
  assert.equal(ledger.entries.length, 1);
  assert.equal(await ledger.apply('shop', 'sale', 123), receipts[0]);
  await assert.rejects(service.pay('shop', 'sale', 124), { message: 'key conflict' });
  assert.equal(ledger.entries.length, 1);
  assert.equal(acknowledged.length, 10);
  assert.notEqual(await service.pay('other', 'sale', 123), receipts[0]);
  assert.notEqual(await service.pay('shop', 'other', 123), receipts[0]);
  // Keys must not collide when tenant/key contain delimiter-like characters.
  assert.notEqual(await ledger.apply('a:b', 'c', 1), await ledger.apply('a', 'b:c', 1));

  const concurrentLedger = new Ledger();
  const outcomes = await Promise.allSettled([
    concurrentLedger.apply('shop', 'sale', 1), concurrentLedger.apply('shop', 'sale', 2),
  ]);
  assert.equal(outcomes[0].status, 'fulfilled');
  assert.equal(outcomes[1].status, 'rejected');
  assert.equal(outcomes[1].reason.message, 'key conflict');
  assert.equal(concurrentLedger.entries.length, 1);

  for (const attempts of [1, 3, 5]) {
    const retryLedger = new Ledger();
    let applies = 0;
    const apply = retryLedger.apply.bind(retryLedger);
    retryLedger.apply = (...args) => { applies++; return apply(...args); };
    const sent = [];
    const errors = Array.from({ length: attempts }, () => new Transient('ack failed'));
    const retryService = new PaymentService(retryLedger, {
      acknowledge: async receipt => { sent.push(receipt); throw errors[sent.length - 1]; },
    });
    await assert.rejects(retryService.pay('shop', 'sale', 123, attempts), error => error === errors.at(-1));
    assert.equal(sent.length, attempts);
    assert.equal(applies, 1);
    assert.equal(retryLedger.entries.length, 1);
    sent.forEach(receipt => assert.equal(receipt, retryLedger.entries[0]));
    const recovered = new PaymentService(retryLedger, { acknowledge: async () => {} });
    assert.equal(await recovered.pay('shop', 'sale', 123), sent[0]);
    assert.equal(retryLedger.entries.length, 1);
  }

  let calls = 0;
  const successLedger = new Ledger();
  const successService = new PaymentService(successLedger, {
    acknowledge: async receipt => {
      assert.equal(receipt, successLedger.entries[0]);
      if (++calls < 3) throw new Transient('retry');
    },
  });
  assert.equal(await successService.pay('shop', 'sale', 1), successLedger.entries[0]);
  assert.equal(calls, 3);
  const fatal = new Error('fatal');
  calls = 0;
  const fatalService = new PaymentService(new Ledger(), {
    acknowledge: async () => { calls++; throw fatal; },
  });
  await assert.rejects(fatalService.pay('shop', 'sale', 1), error => error === fatal);
  assert.equal(calls, 1);

  const invalidService = new PaymentService({ apply: async () => assert.fail('ledger called') }, {
    acknowledge: async () => assert.fail('transport called'),
  });
  for (const args of [
    ['', 'key', 1], ['tenant', '', 1], [null, 'key', 1], ['tenant', 1, 1],
    ['tenant', 'key', 0], ['tenant', 'key', -1], ['tenant', 'key', 1.5],
    ['tenant', 'key', NaN], ['tenant', 'key', Infinity],
    ...[0, -1, 6, 1.5, NaN, Infinity, '3', null].map(n => ['tenant', 'key', 1, n]),
  ]) {
    await assert.rejects(invalidService.pay(...args), { message: 'invalid payment' });
  }
  const invalidLedger = new Ledger();
  await assert.rejects(invalidLedger.apply('', 'key', 1), { message: 'invalid payment' });
  assert.equal(invalidLedger.entries.length, 0);
}

module.exports = main();
EOF
